#!/usr/bin/env python3
"""PostToolUse(Edit|Write) hook: nudge decomposition when the agent GROWS a
source file past the threshold. Compares against the git HEAD baseline so
merely editing a pre-existing large file stays silent, and nags at most
once per file per session (re-nagging only after another 20% growth).
Reads hook JSON on stdin, emits hookSpecificOutput.additionalContext on
stdout. Always exits 0; a broken guard must never block real work.

Threshold defaults to 500 lines; override per repo with the
FILE_SIZE_GUARD_THRESHOLD environment variable (for example via the `env`
block of the project's .claude/settings.json). See INSTALL.md for wiring."""

from __future__ import annotations

import json
import os
import subprocess
import sys
import tempfile
from pathlib import Path


def _threshold() -> int:
    raw = os.environ.get("FILE_SIZE_GUARD_THRESHOLD", "")
    try:
        value = int(raw)
    except ValueError:
        return 500
    return value if value > 0 else 500


THRESHOLD = _threshold()
RENAG_GROWTH = 0.2  # nag again only after the file grows another 20%
SOURCE_EXTS = {
    ".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", ".mts", ".cts",
    ".py", ".go", ".rs", ".java", ".kt", ".rb", ".php", ".swift",
    ".c", ".cc", ".cpp", ".h", ".hpp", ".cs", ".vue", ".svelte",
}
SKIP_DIRS = {"node_modules", "dist", "build", ".git", "vendor", "__pycache__"}
GENERATED_MARKERS = ("auto-generated", "@generated", "do not edit", "autogenerated")


def count_lines(path: Path) -> int | None:
    """Line count, or None for unreadable/generated files."""
    try:
        with path.open(encoding="utf-8", errors="replace") as f:
            head = "".join(f.readline() for _ in range(5))
            if any(m in head.lower() for m in GENERATED_MARKERS):
                return None
            return 5 + sum(1 for _ in f)
    except OSError:
        return None


def head_baseline(path: Path) -> int | None:
    """Line count at git HEAD; 0 if the file is new to the repo; None if
    no git repo or git is unavailable (baseline unknown)."""
    try:
        show = subprocess.run(
            ["git", "-C", str(path.parent), "show", f"HEAD:./{path.name}"],
            capture_output=True, timeout=2,
        )
    except (OSError, subprocess.SubprocessError):
        return None
    if show.returncode == 0:
        return show.stdout.count(b"\n")
    try:
        repo = subprocess.run(
            ["git", "-C", str(path.parent), "rev-parse", "--is-inside-work-tree"],
            capture_output=True, timeout=2,
        )
    except (OSError, subprocess.SubprocessError):
        return None
    return 0 if repo.returncode == 0 else None


def load_state(session_id: str) -> tuple[Path, dict]:
    state_path = Path(tempfile.gettempdir()) / f"claude-fsg-{session_id}.json"
    try:
        state = json.loads(state_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        state = {}
    state.setdefault("seen", {})
    state.setdefault("nagged", {})
    return state_path, state


def main() -> None:
    try:
        payload = json.load(sys.stdin)
    except (json.JSONDecodeError, ValueError):
        return
    file_path = (payload.get("tool_input") or {}).get("file_path", "")
    if not file_path:
        return
    path = Path(file_path)
    if path.suffix.lower() not in SOURCE_EXTS or SKIP_DIRS.intersection(path.parts):
        return

    lines = count_lines(path)
    if lines is None:
        return

    session_id = payload.get("session_id") or "nosession"
    state_path, state = load_state(session_id)
    key = str(path)

    if lines <= THRESHOLD:
        # Dropped back under the threshold (decomposed or trimmed): reset.
        if state["nagged"].pop(key, None) is not None:
            _save(state_path, state)
        return

    baseline = head_baseline(path)
    if baseline is None:
        # No git baseline: use the first size seen this session, so a file
        # that was already large when the session started stays silent.
        baseline = state["seen"].setdefault(key, lines)
        _save(state_path, state)

    crossed = baseline <= THRESHOLD < lines
    bloating = baseline > THRESHOLD and lines - baseline >= max(100, int(baseline * RENAG_GROWTH))
    if not (crossed or bloating):
        return

    last_nag = state["nagged"].get(key)
    if last_nag is not None and lines < last_nag * (1 + RENAG_GROWTH):
        return  # already told this session; stay quiet until real further growth

    state["nagged"][key] = lines
    _save(state_path, state)

    if crossed:
        situation = (
            f"grew from {baseline} to {lines} lines this session, "
            f"crossing the {THRESHOLD}-line decomposition threshold"
        )
    else:
        situation = (
            f"was already {baseline} lines and has grown to {lines} under "
            "this session's edits"
        )
    print(json.dumps({
        "hookSpecificOutput": {
            "hookEventName": "PostToolUse",
            "additionalContext": (
                f"file-size-guard: {file_path} {situation}. If decomposing it "
                "by responsibility fits the current task's scope, do that; "
                "otherwise finish the task and flag the decomposition to the "
                "user as a follow-up. Do not silently keep appending, and do "
                "not derail a focused fix into a drive-by refactor. If the "
                "size is justified (cohesive single concern, data table), "
                "say why once. This reminder fires once per file per session."
            ),
        }
    }))


def _save(state_path: Path, state: dict) -> None:
    try:
        state_path.write_text(json.dumps(state), encoding="utf-8")
    except OSError:
        pass


if __name__ == "__main__":
    main()
